import json
import subprocess
import sys


def main():
    try:
        with open('inputs.json', 'r', encoding='utf-8') as f:
            cases = json.load(f)
    except Exception as e:
        print(json.dumps({'results': [], 'harness_error': 'failed to read inputs.json: ' + str(e)}))
        return 0

    results = []
    for case in cases:
        cid = case.get('id') if isinstance(case, dict) else None
        inp = case.get('input') if isinstance(case, dict) else None
        stdin_text = ''
        if isinstance(inp, dict) and isinstance(inp.get('stdin', ''), str):
            stdin_text = inp.get('stdin', '')
        try:
            proc = subprocess.run(
                [sys.executable, '-I', 'block-0.txt'],
                input=stdin_text.encode('utf-8'),
                capture_output=True,
                timeout=5,
            )
        except subprocess.TimeoutExpired:
            results.append({'id': cid, 'error': 'candidate timed out after 5 seconds'})
            continue
        except OSError as e:
            print(json.dumps({'results': results, 'harness_error': 'failed to launch candidate: ' + str(e)}))
            return 0
        results.append({
            'id': cid,
            'actual': {
                'stdout': proc.stdout.decode('utf-8', errors='replace'),
                'exit_code': proc.returncode,
            },
        })

    print(json.dumps({'results': results}))
    return 0


if __name__ == '__main__':
    sys.exit(main())
